#include <iostream>
#include <memory>
#include <queue>
#include <vector>

struct TreeNode {
    int val;
    std::unique_ptr<TreeNode> left;
    std::unique_ptr<TreeNode> right;
    explicit TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

class BST {
public:
    void insert(int v) {
        insertHelper(root, v);
    }

    void eraseValue(int v) {
        root = deleteHelper(std::move(root), v);
    }

    void printLevelOrder() const {
        if (!root) return;
        std::queue<const TreeNode*> q;
        q.push(root.get());
        bool first = true;
        while (!q.empty()) {
            const TreeNode* curr = q.front();
            q.pop();
            if (!first) std::cout << " ";
            std::cout << curr->val;
            first = false;
            if (curr->left) q.push(curr->left.get());
            if (curr->right) q.push(curr->right.get());
        }
        std::cout << "\n";
    }

private:
    std::unique_ptr<TreeNode> root;

    static void insertHelper(std::unique_ptr<TreeNode>& node, int v) {
        if (!node) {
            node = std::make_unique<TreeNode>(v);
        } else if (v < node->val) {
            insertHelper(node->left, v);
        } else if (v > node->val) {
            insertHelper(node->right, v);
        }
    }

    static int findMin(const TreeNode* node) {
        while (node->left) node = node->left.get();
        return node->val;
    }

    static std::unique_ptr<TreeNode> deleteHelper(std::unique_ptr<TreeNode> node, int v) {
        if (!node) return nullptr;
        if (v < node->val) {
            node->left = deleteHelper(std::move(node->left), v);
        } else if (v > node->val) {
            node->right = deleteHelper(std::move(node->right), v);
        } else {
            if (!node->left) return std::move(node->right);
            if (!node->right) return std::move(node->left);
            node->val = findMin(node->right.get());
            node->right = deleteHelper(std::move(node->right), node->val);
        }
        return node;
    }
};

int main() {
    BST tree;
    for (int v : {49, 28, 83, 18, 40, 71, 97}) {
        tree.insert(v);
    }
    std::cout << "Level-order before delete: ";
    tree.printLevelOrder();

    tree.eraseValue(28);
    std::cout << "Level-order after deleting 28: ";
    tree.printLevelOrder();
    return 0;
}

#include <iostream>
#include <string>

struct Node {
    int data;
    Node* left{nullptr};
    Node* right{nullptr};
    explicit Node(int val) : data(val) {}
};

void outputTree(const Node* node, int totalSpaces = 0) {
    if (node == nullptr) return;

    outputTree(node->right, totalSpaces + 5);
    std::cout << std::string(totalSpaces, ' ') << node->data << "\n";
    outputTree(node->left, totalSpaces + 5);
}

Node* insert(Node* root, int val) {
    if (!root) return new Node(val);
    if (val < root->data) root->left = insert(root->left, val);
    else if (val > root->data) root->right = insert(root->right, val);
    return root;
}

void destroyTree(Node* root) {
    if (!root) return;
    destroyTree(root->left);
    destroyTree(root->right);
    delete root;
}

int main() {
    Node* root = nullptr;
    for (int v : {49, 83, 28, 97, 71, 40, 18}) {
        root = insert(root, v);
    }

    std::cout << "Horizontal tree output:\n";
    outputTree(root, 0);

    destroyTree(root);
    return 0;
}
